@push('script')
<script>
document.addEventListener('DOMContentLoaded',()=>{
 const SELF_ONLY=@json($selfOnly),API=SELF_ONLY?'/api/hc/daily-work?scope=self':'/api/hc/daily-work',state={tasks:[],approvalTasks:[],user:'',currentUserId:null,people:[],assignablePeople:[],projects:[],divisions:[],kpis:[],formDivisionId:null,divisionLocked:false,timelineScale:2,workdayStart:9,workdayEnd:17},byId=id=>document.getElementById(id),csrf=document.querySelector('meta[name="csrf-token"]')?.content||'';
 const esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
 const time=value=>{let n=Number(value||0),h=Math.floor(n/60),m=n%60;return h?`${h}j ${m?`${m}m`:''}`.trim():`${m}m`};
 const priorities={1:['Rendah','bg-sky-50 text-sky-700'],2:['Sedang','bg-amber-50 text-amber-700'],3:['Tinggi','bg-rose-50 text-rose-700']};
 const tones={0:'bg-zinc-100 text-zinc-700',1:'bg-emerald-50 text-emerald-700',2:'bg-orange-50 text-orange-700',3:'bg-violet-50 text-violet-700',4:'bg-sky-50 text-sky-700',5:'bg-zinc-100 text-zinc-600',7:'bg-rose-50 text-rose-700',8:'bg-red-50 text-red-700',9:'bg-violet-50 text-violet-700'};
 function notify(message,error=false){let e=byId('toast');e.textContent=message;e.className=`fixed bottom-5 right-5 z-[120] max-w-sm rounded-2xl px-4 py-3 text-sm font-medium text-white shadow-xl ${error?'bg-rose-600':'bg-zinc-950'}`;clearTimeout(e.timer);e.timer=setTimeout(()=>e.classList.add('hidden'),3000)}
 async function call(url,options={}){let response=await fetch(url,{headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf},...options});if(!response.ok)throw new Error((await response.json().catch(()=>({}))).message||'Permintaan gagal diproses.');return response.json()}
 function proofLink(t){if(!t.proof)return '';let size=t.proof.size?` · ${(Number(t.proof.size)/1024/1024).toFixed(2)} MB`:'';return `<a href="${esc(t.proof.url)}" target="_blank" rel="noopener" class="mt-3 flex items-center justify-between gap-3 rounded-xl border border-lime-200 bg-lime-50 px-3 py-2.5 text-xs text-lime-900 transition hover:bg-lime-100"><span class="min-w-0"><b class="block text-[10px] uppercase tracking-wider text-lime-700">Bukti penyelesaian</b><span class="mt-0.5 block truncate font-semibold">${esc(t.proof.name)}${size}</span></span><span class="shrink-0 font-bold">Lihat ↗</span></a>`}
 function loading(){let cards=Array(3).fill('<div class="h-28 animate-pulse rounded-2xl bg-zinc-100"></div>').join('');byId('pool-list').innerHTML=cards;byId('schedule-list').innerHTML=cards;byId('approval-list').innerHTML=cards}
 async function load(keep=false){loading();try{let data=await call(API+(state.user?`?user_id=${encodeURIComponent(state.user)}`:''));state.tasks=data.tasks||[];state.approvalTasks=data.approval_tasks||[];state.user=String(data.selected_user_id||'');state.currentUserId=Number(data.current_user?.id||0);state.people=data.people||[];state.assignablePeople=data.assignable_people||[];state.projects=data.projects||[];state.divisions=data.divisions||[];state.kpis=data.kpis||[];state.formDivisionId=data.form_division_id?Number(data.form_division_id):null;state.divisionLocked=Boolean(data.division_locked);state.workdayStart=Number(data.workday_start||9);state.workdayEnd=Number(data.workday_end||17);byId('current-date').textContent=new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(`${data.date}T00:00:00`));if(!keep||!byId('user-filter').options.length)byId('user-filter').innerHTML=state.people.map(x=>`<option value="${x.id}">${esc(x.email)}</option>`).join('');byId('user-filter').value=state.user;summary(data.summary||{});render()}catch(error){notify(error.message,true);byId('pool-list').innerHTML=empty('Data gagal dimuat','Tekan Perbarui untuk mencoba lagi.');byId('schedule-list').innerHTML=empty('Data gagal dimuat','Tekan Perbarui untuk mencoba lagi.');byId('approval-list').innerHTML=empty('Data gagal dimuat','Tekan Perbarui untuk mencoba lagi.')}}
 function summary(s){let cards=[['Terjadwal',s.scheduled||0,'Hari ini','bg-zinc-950 text-white'],['Task Pool',s.pool||0,time(s.pool_minutes),'bg-white'],['Sedang Berjalan',s.running||0,'Task aktif','bg-emerald-50'],['Perlu Approval',s.approval||0,'Menunggu review','bg-violet-50']];byId('summary').innerHTML=cards.map(x=>`<article class="rounded-2xl border border-zinc-200 ${x[3]} p-4 shadow-sm sm:p-5"><p class="text-[11px] font-bold uppercase tracking-[.16em] opacity-60">${x[0]}</p><div class="mt-3 flex items-end justify-between"><strong class="text-3xl font-semibold">${x[1]}</strong><span class="text-xs opacity-60">${x[2]}</span></div></article>`).join('')}
 function filtered(source=state.tasks){let status=byId('status-filter').value,q=byId('search-filter').value.trim().toLowerCase();return source.filter(t=>(status==='all'||String(t.status)===status)&&(!q||[t.name,t.project,t.kpi,t.pic].some(v=>String(v||'').toLowerCase().includes(q))))}
 function actions(t){if([0,2,7,8].includes(t.status))return `<div class="flex gap-1"><button data-action="play" data-id="${t.id}" class="rounded-lg bg-emerald-600 px-3 py-1.5 text-xs font-bold text-white">Mulai</button><button data-reset="${t.id}" class="rounded-lg border border-zinc-200 px-2 py-1.5 text-xs font-bold">Pool</button></div>`;if(t.status===1)return `<button data-action="stop" data-id="${t.id}" class="rounded-lg bg-zinc-950 px-3 py-1.5 text-xs font-bold text-white">Selesaikan</button>`;if([3,9].includes(t.status)){if(Number(t.pic_id)===state.currentUserId)return '<span class="rounded-lg bg-violet-50 px-3 py-1.5 text-xs font-bold text-violet-700">Menunggu persetujuan</span>';return `<div class="flex gap-1"><button data-action="approve" data-id="${t.id}" class="rounded-lg bg-emerald-600 px-2 py-1.5 text-xs font-bold text-white">Setujui</button><button data-action="revisi" data-id="${t.id}" class="rounded-lg bg-orange-500 px-2 py-1.5 text-xs font-bold text-white">Revisi</button></div>`}return '<span class="text-xs font-semibold text-zinc-400">Tuntas</span>'}
 function approvalActions(t){if(Number(t.pic_id)===state.currentUserId)return '<span class="rounded-lg bg-violet-50 px-3 py-1.5 text-xs font-bold text-violet-700">Menunggu persetujuan</span>';return `<div class="flex gap-1"><button data-action="approve" data-id="${t.id}" class="rounded-lg bg-zinc-950 px-3 py-1.5 text-xs font-bold text-white">Setujui</button><button data-action="revisi" data-id="${t.id}" class="rounded-lg border border-zinc-300 bg-white px-3 py-1.5 text-xs font-bold text-zinc-800">Revisi</button></div>`}
 function card(t,scheduled){let p=priorities[t.priority]||priorities[1],kpi=t.kpi?`<div class="mt-3 flex items-start gap-2 rounded-xl bg-lime-50 px-3 py-2 text-xs text-lime-900"><b class="shrink-0 text-lime-700">KPI</b><span class="line-clamp-2">${esc(t.kpi)}</span></div>`:'',note=t.note?`<div class="mt-2 rounded-xl bg-zinc-50 px-3 py-2 text-xs leading-5 text-zinc-600"><b class="mr-1 text-zinc-800">Note:</b><span class="line-clamp-3">${esc(t.note)}</span></div>`:'',crud=t.status===0?`<button data-edit="${t.id}" class="rounded-lg border border-amber-200 bg-amber-50 px-2 py-1.5 text-xs font-bold text-amber-700">Edit</button><button data-delete="${t.id}" class="rounded-lg border border-rose-200 bg-rose-50 px-2 py-1.5 text-xs font-bold text-rose-700">Hapus</button>`:'';return `<article draggable="${t.status===0}" data-drag-task="${t.id}" class="group rounded-2xl border border-zinc-200 bg-white p-4 transition hover:-translate-y-0.5 hover:shadow-lg ${t.status===0?'cursor-grab active:cursor-grabbing':''}"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><p class="truncate text-xs font-bold uppercase tracking-wider text-zinc-400">${esc(t.project)}</p><button data-detail="${t.id}" class="mt-1 text-left text-sm font-semibold hover:underline">${esc(t.name)}</button></div><span class="rounded-full px-2 py-1 text-[10px] font-bold ${p[1]}">${p[0]}</span></div>${kpi}${note}<div class="mt-3 flex flex-wrap gap-2 text-xs text-zinc-500"><span class="rounded-lg px-2 py-1 font-semibold ${tones[t.status]||tones[0]}">${esc(t.status_label)}</span><span>${time(t.minutes)}</span></div><div class="mt-4 flex flex-wrap items-center justify-between gap-2 border-t border-zinc-100 pt-3"><span class="text-xs text-zinc-500">${esc(t.pic)}</span><div class="flex gap-1">${scheduled?actions(t):`<button data-schedule="${t.id}" class="rounded-lg bg-zinc-950 px-3 py-1.5 text-xs font-bold text-white">Jadwalkan</button>`}${crud}</div></div></article>`}
 function approvalCard(t){let p=priorities[t.priority]||priorities[1],date=t.start_date?new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${t.start_date}T00:00:00`)):'-';return `<article class="rounded-2xl border border-zinc-200 bg-white p-4 shadow-sm"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><p class="truncate text-[10px] font-bold uppercase tracking-wider text-zinc-400">${esc(t.project)}</p><button data-detail="${t.id}" class="mt-1 text-left text-sm font-semibold hover:underline">${esc(t.name)}</button></div><span class="rounded-full px-2 py-1 text-[10px] font-bold ${p[1]}">${p[0]}</span></div><div class="mt-3 grid grid-cols-2 gap-2 text-xs"><div class="rounded-xl bg-zinc-50 p-2"><span class="block text-[10px] font-bold uppercase text-zinc-400">PIC</span><span class="mt-1 block truncate font-semibold">${esc(t.pic)}</span></div><div class="rounded-xl bg-zinc-50 p-2"><span class="block text-[10px] font-bold uppercase text-zinc-400">Mulai</span><span class="mt-1 block font-semibold">${date}${t.start_time?` · ${esc(t.start_time)}`:''}</span></div></div>${t.kpi?`<p class="mt-3 rounded-xl bg-zinc-50 px-3 py-2 text-xs"><b>KPI:</b> ${esc(t.kpi)}</p>`:''}${t.note?`<p class="mt-2 line-clamp-3 text-xs leading-5 text-zinc-500"><b class="text-zinc-700">Note:</b> ${esc(t.note)}</p>`:''}${proofLink(t)}<div class="mt-4 flex items-center justify-between gap-2 border-t border-zinc-100 pt-3"><span class="rounded-lg px-2 py-1 text-[10px] font-bold ${tones[t.status]||tones[0]}">${esc(t.status_label)}</span>${approvalActions(t)}</div></article>`}
 function empty(title,text){return `<div class="flex min-h-52 flex-col items-center justify-center rounded-2xl border border-dashed border-zinc-200 bg-zinc-50 p-8 text-center"><span class="mb-3 h-10 w-10 rounded-full bg-zinc-200"></span><p class="font-semibold">${title}</p><p class="mt-1 text-sm text-zinc-500">${text}</p></div>`}
 function timelineCard(t){let p=priorities[t.priority]||priorities[1],left=`calc(${t.lane/t.lanes*100}% + 10px)`,width=`calc(${100/t.lanes}% - 14px)`,position=`top:${t.top}px;height:${t.height}px;left:${left};width:${width}`,tooltip=[`${t.start_time} · ${t.name}`,t.kpi?`KPI: ${t.kpi}`:'',t.note?`Note: ${t.note}`:''].filter(Boolean).join(' | ');if(t.height<22)return `<button data-detail="${t.id}" draggable="${t.status===0}" data-drag-task="${t.id}" title="${esc(tooltip)}" style="${position}" class="absolute z-10 rounded-sm border border-zinc-400 bg-zinc-700 hover:z-30 hover:bg-lime-500"></button>`;return `<article draggable="${t.status===0}" data-drag-task="${t.id}" title="${esc(tooltip)}" style="${position}" class="absolute z-10 overflow-hidden rounded-xl border border-zinc-200 bg-white px-3 py-2 shadow-sm transition hover:z-30 hover:shadow-lg ${t.status===1?'border-emerald-300 bg-emerald-50':t.status===7?'border-rose-300 bg-rose-50':''} ${t.status===0?'cursor-grab':''}"><div class="flex h-full items-center justify-between gap-2"><button data-detail="${t.id}" class="min-w-0 flex-1 text-left"><span class="block truncate text-[10px] font-bold uppercase tracking-wider text-zinc-400">${esc(t.start_time)}–${endTime(t.start_time,t.minutes)} · ${esc(t.project)}</span><strong class="block truncate text-xs text-zinc-950 sm:text-sm">${esc(t.name)}</strong>${t.height>=54?`<span class="block truncate text-[10px] font-medium text-lime-700">${t.kpi?`KPI: ${esc(t.kpi)}`:'Tanpa KPI'}</span>`:''}${t.height>=78&&t.note?`<span class="block truncate text-[10px] text-zinc-500">Note: ${esc(t.note)}</span>`:''}${t.height>=100?`<span class="block truncate text-[10px] text-zinc-400">PIC: ${esc(t.pic)}</span>`:''}</button><div class="flex shrink-0 items-center gap-1">${actions(t)}${t.status===0?`<button data-edit="${t.id}" class="rounded-lg bg-amber-50 px-2 py-1.5 text-[10px] font-bold text-amber-700">Edit</button><button data-delete="${t.id}" class="rounded-lg bg-rose-50 px-2 py-1.5 text-[10px] font-bold text-rose-700">Hapus</button>`:''}</div></div></article>`}
 function endTime(start,minutes){let [h,m]=start.split(':').map(Number),total=(h*60+m+Number(minutes))%(24*60);return `${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`}
 function layoutTimeline(scheduled){let laneEnds=[],scale=state.timelineScale,minPixels=scale<.5?4:scale<1?14:28,items=scheduled.map(t=>{let [h,m]=t.start_time.split(':').map(Number),start=Math.max(0,(h-state.workdayStart)*60+m),visualMinutes=Math.max(Number(t.minutes),minPixels/scale),lane=laneEnds.findIndex(end=>end<=start);if(lane<0)lane=laneEnds.length;laneEnds[lane]=start+visualMinutes;return {...t,lane,top:start*scale,height:visualMinutes*scale}}),lanes=Math.max(1,laneEnds.length);return items.map(t=>({...t,lanes}))}
 function timeline(scheduled){let labels='',lines='',scale=state.timelineScale,totalMinutes=(state.workdayEnd-state.workdayStart)*60,height=totalMinutes*scale,items=layoutTimeline(scheduled);for(let h=state.workdayStart;h<=state.workdayEnd;h++){labels+=`<div style="top:${(h-state.workdayStart)*60*scale}px" class="absolute right-3 -translate-y-1/2 text-[11px] font-bold text-zinc-500">${String(h).padStart(2,'0')}:00</div>`;if(h<state.workdayEnd){lines+=`<div style="top:${(h-state.workdayStart)*60*scale}px" class="absolute inset-x-0 border-t border-zinc-200"></div>`;for(let m=10;m<60;m+=10)lines+=`<div style="top:${((h-state.workdayStart)*60+m)*scale}px" class="absolute inset-x-0 border-t border-dashed border-zinc-100"></div>`}}return `<div class="grid min-w-[760px] grid-cols-[78px_minmax(0,1fr)]"><div style="height:${height}px" class="relative border-r border-zinc-200 bg-zinc-50">${labels}</div><div id="timeline-grid" style="height:${height}px" class="relative bg-white">${lines}${items.map(timelineCard).join('')}</div></div>`}
 function render(){let tasks=filtered(),pool=tasks.filter(t=>!t.start_time),scheduled=tasks.filter(t=>t.start_time).sort((a,b)=>a.start_time.localeCompare(b.start_time)),approval=filtered(state.approvalTasks);byId('pool-count').textContent=pool.length;byId('pool-list').innerHTML=pool.length?pool.map(t=>card(t,false)).join(''):empty('Task pool kosong','Semua task sudah masuk ke jadwal.');byId('schedule-list').innerHTML=timeline(scheduled);byId('duration').textContent=`${time(scheduled.reduce((a,t)=>a+t.minutes,0))} terjadwal`;byId('zoom-level').textContent=`${Math.round(state.timelineScale/2*100)}%`;byId('approval-count').textContent=approval.length;byId('approval-tab-count').textContent=approval.length;byId('approval-list').innerHTML=approval.length?approval.map(approvalCard).join(''):empty('Tidak ada task untuk direview','Task yang dikirim bawahan untuk persetujuan akan tampil di sini.');bindTimelineDrop()}
 function bindTimelineDrop(){let grid=byId('timeline-grid');if(!grid)return;grid.addEventListener('dragover',e=>{e.preventDefault();grid.classList.add('bg-lime-50')});grid.addEventListener('dragleave',()=>grid.classList.remove('bg-lime-50'));grid.addEventListener('drop',e=>{e.preventDefault();grid.classList.remove('bg-lime-50');let id=e.dataTransfer.getData('text/task-id'),task=state.tasks.find(t=>Number(t.id)===Number(id));if(!id||!task)return;let rect=grid.getBoundingClientRect(),minutes=Math.max(0,Math.round(((e.clientY-rect.top)/state.timelineScale)/10)*10),available=(state.workdayEnd-state.workdayStart)*60;if(minutes+Number(task.minutes)>available){notify('Task tidak dapat dijadwalkan karena akan selesai melewati pukul 17.00 WIB.',true);return}mutate('/api/hc/update-schedule',{id,top:minutes},'Jadwal task diperbarui.')})}
 async function mutate(url,payload,message,method='POST'){try{await call(url,{method,body:JSON.stringify(payload)});notify(message);await load(true)}catch(error){notify(error.message,true)}}
 function openProof(id){byId('proof-form').reset();byId('proof-task-id').value=id;byId('proof-file-name').textContent='';byId('proof-file-name').classList.add('hidden');byId('proof-modal').classList.replace('hidden','flex')}
 function closeProof(){byId('proof-modal').classList.replace('flex','hidden')}
 async function submitProof(event){event.preventDefault();let file=byId('proof-file').files[0];if(!file){notify('Pilih gambar atau file bukti terlebih dahulu.',true);return}if(file.size>10*1024*1024){notify('Ukuran bukti maksimal 10 MB.',true);return}let body=new FormData();body.append('id',byId('proof-task-id').value);body.append('action','stop');body.append('proof',file);let button=byId('send-proof');button.disabled=true;button.textContent='Mengirim...';try{let response=await fetch('/api/hc/update-status',{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf},body});if(!response.ok)throw new Error((await response.json().catch(()=>({}))).message||'Bukti gagal dikirim.');closeProof();notify('Task dan bukti berhasil dikirim untuk approval.');await load(true)}catch(error){notify(error.message,true)}finally{button.disabled=false;button.textContent='Kirim untuk Approval'}}
 function detail(id){let t=[...state.tasks,...state.approvalTasks].find(x=>Number(x.id)===Number(id));if(!t)return;byId('modal-project').textContent=t.project;byId('modal-title').textContent=t.name;let rows=[['PIC',t.pic],['Status',t.status_label],['Durasi',time(t.minutes)],['Jadwal',t.start_time?`${t.start_date||''} · ${t.start_time} WIB`:'Belum dijadwalkan'],['Deadline',t.deadline||'-'],['KPI',t.kpi||'-']];byId('modal-content').innerHTML=`<dl class="grid grid-cols-2 gap-3">${rows.map(x=>`<div class="rounded-xl bg-zinc-50 p-3"><dt class="text-[10px] font-bold uppercase tracking-wider text-zinc-400">${x[0]}</dt><dd class="mt-1 text-sm font-semibold">${esc(x[1])}</dd></div>`).join('')}</dl>${t.note?`<div><p class="text-xs font-bold uppercase tracking-wider text-zinc-400">Catatan</p><p class="mt-2 whitespace-pre-line text-sm leading-6 text-zinc-700">${esc(t.note)}</p></div>`:''}${proofLink(t)}`;byId('modal-actions').innerHTML='<button data-close class="rounded-xl border border-zinc-200 bg-white px-4 py-2 text-sm font-semibold">Tutup</button>';byId('task-modal').classList.replace('hidden','flex')}
 function close(){byId('task-modal').classList.replace('flex','hidden')}
 function refreshProjectOptions(selected=''){let divisionId=Number(byId('form-division').value),projects=state.projects.filter(x=>Number(x.division_id)===divisionId),unique=[...new Map(projects.map(x=>[Number(x.id),x])).values()];byId('form-project').innerHTML=unique.length?unique.map(x=>`<option value="${x.id}">${esc(x.nama)}</option>`).join(''):'<option value="">Tidak ada project pada divisi ini</option>';if(selected&&unique.some(x=>Number(x.id)===Number(selected)))byId('form-project').value=selected;refreshKpiOptions()}
 function refreshKpiOptions(selected=''){let divisionId=Number(byId('form-division').value),projectId=Number(byId('form-project').value),kpis=state.kpis.filter(x=>Number(x.division_id)===divisionId&&Number(x.project_id)===projectId);byId('form-kpi').innerHTML='<option value="">Tanpa KPI</option>'+kpis.map(x=>`<option value="${x.id}">${esc(x.nama_kpi)}</option>`).join('');if(selected&&kpis.some(x=>Number(x.id)===Number(selected)))byId('form-kpi').value=selected}
 function formOptions(){byId('form-division').innerHTML=state.divisions.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');if(state.formDivisionId)byId('form-division').value=state.formDivisionId;byId('form-division-field').classList.toggle('hidden',state.divisionLocked);byId('form-pic').innerHTML=state.assignablePeople.map(x=>`<option value="${x.id}">${esc(x.email)}</option>`).join('');refreshProjectOptions()}
 function formStartHour(){let division=state.divisions.find(x=>String(x.id)===String(byId('form-division').value));return String(division?.name||'').trim().toLowerCase()==='tech'?8:9}
 function updateEndPreview(){let start=byId('form-start-time').value,minutes=Number(byId('form-minutes').value),startHour=formStartHour(),end=start&&minutes>0?endTime(start,minutes):null,[hour,minute]=start?start.split(':').map(Number):[0,0],invalid=Boolean(start)&&(hour*60+minute<startHour*60||hour*60+minute+minutes>17*60);byId('form-start-time').min=`${String(startHour).padStart(2,'0')}:00`;byId('form-start-time').max='16:59';byId('form-hours-hint').textContent=`Jam kerja divisi ini ${String(startHour).padStart(2,'0')}.00–17.00 WIB.`;byId('form-end-time').textContent=end?`${end} WIB`:'--:--';byId('form-end-time').classList.toggle('border-rose-300',invalid);byId('form-end-time').classList.toggle('text-rose-700',invalid);byId('form-time-error').classList.toggle('hidden',!invalid);return !invalid}
 function openForm(task=null){byId('task-form').reset();formOptions();byId('form-id').value=task?.id||'';byId('form-title').textContent=task?'Edit Task':'Tambah Task';let today=new Date().toISOString().slice(0,10),divisionId=state.divisionLocked?state.formDivisionId:(task?.division_id||state.formDivisionId||state.divisions[0]?.id);byId('form-name').value=task?.name||'';byId('form-division').value=divisionId||'';refreshProjectOptions(task?.project_id||'');refreshKpiOptions(task?.kpi_id||'');byId('form-pic').value=task?.pic_id||state.user;if(!byId('form-pic').value&&state.assignablePeople.length)byId('form-pic').value=state.assignablePeople[0].id;byId('form-priority').value=task?.priority||1;byId('form-minutes').value=task?.minutes||60;byId('form-start-date').value=task?.start_date||today;byId('form-deadline').value=task?.deadline||today;byId('form-start-time').value=task?.start_time||'';byId('form-note').value=task?.note||'';updateEndPreview();byId('form-modal').classList.replace('hidden','flex')}
 function closeForm(){byId('form-modal').classList.replace('flex','hidden')}
 async function saveForm(event){event.preventDefault();if(!updateEndPreview()){notify('Periksa jam mulai dan durasi. Task harus selesai paling lambat pukul 17.00 WIB.',true);return}let id=byId('form-id').value,payload={name:byId('form-name').value,project_id:Number(byId('form-project').value),division_id:Number(byId('form-division').value),pic_id:Number(byId('form-pic').value),kpi_id:byId('form-kpi').value?Number(byId('form-kpi').value):null,priority:Number(byId('form-priority').value),minutes:Number(byId('form-minutes').value),start_date:byId('form-start-date').value,deadline:byId('form-deadline').value,start_time:byId('form-start-time').value,note:byId('form-note').value||null};let button=byId('save-task');button.disabled=true;button.textContent='Menyimpan...';try{await call(`${API}/tasks${id?`/${id}`:''}`,{method:id?'PUT':'POST',body:JSON.stringify(payload)});closeForm();notify(id?'Task berhasil diperbarui.':'Task berhasil ditambahkan.');await load(true)}catch(error){notify(error.message,true)}finally{button.disabled=false;button.textContent='Simpan Task'}}
 document.addEventListener('dragstart',e=>{let task=e.target.closest('[data-drag-task]');if(task&&task.getAttribute('draggable')==='true'){e.dataTransfer.setData('text/task-id',task.dataset.dragTask);e.dataTransfer.effectAllowed='move'}});
 document.addEventListener('click',e=>{let d=e.target.closest('[data-detail]');if(d)detail(d.dataset.detail);let edit=e.target.closest('[data-edit]');if(edit)openForm(state.tasks.find(x=>Number(x.id)===Number(edit.dataset.edit)));let del=e.target.closest('[data-delete]');if(del&&confirm('Hapus task ini secara permanen?'))mutate(`${API}/tasks/${del.dataset.delete}`,{},'Task berhasil dihapus.','DELETE');let s=e.target.closest('[data-schedule]');if(s){let now=new Date(),task=state.tasks.find(t=>Number(t.id)===Number(s.dataset.schedule)),division=state.divisions.find(x=>Number(x.id)===Number(task?.division_id)),startHour=String(division?.name||'').trim().toLowerCase()==='tech'?8:9,top=Math.max(0,(now.getHours()-startHour)*60+now.getMinutes()),available=(17-startHour)*60;if(!task||top+Number(task.minutes)>available){notify('Task tidak dapat dijadwalkan karena akan selesai melewati pukul 17.00 WIB.',true)}else{mutate('/api/hc/update-schedule',{id:s.dataset.schedule,top},'Task dimasukkan ke jadwal.')}}let a=e.target.closest('[data-action]');if(a){if(a.dataset.action==='stop')openProof(a.dataset.id);else mutate('/api/hc/update-status',{id:a.dataset.id,action:a.dataset.action},'Status task diperbarui.')}let r=e.target.closest('[data-reset]');if(r&&confirm('Kembalikan task ini ke Task Pool?'))mutate('/api/hc/update-schedule',{id:r.dataset.reset,reset:true},'Task dikembalikan ke pool.');if(e.target.closest('[data-close]')||e.target===byId('task-modal'))close();if(e.target.closest('[data-close-form]')||e.target===byId('form-modal'))closeForm();if(e.target.closest('[data-close-proof]')||e.target===byId('proof-modal'))closeProof()});
 byId('schedule-list').addEventListener('wheel',event=>{if(!event.shiftKey)return;event.preventDefault();let grid=byId('timeline-grid');if(!grid)return;let oldScale=state.timelineScale,rect=grid.getBoundingClientRect(),maxMinutes=(state.workdayEnd-state.workdayStart)*60,minute=Math.max(0,Math.min(maxMinutes,(event.clientY-rect.top)/oldScale)),factor=event.deltaY<0?1.18:1/1.18,newScale=Math.max(.15,Math.min(8,oldScale*factor));if(Math.abs(newScale-oldScale)<.001)return;state.timelineScale=newScale;render();requestAnimationFrame(()=>{let nextGrid=byId('timeline-grid');if(!nextGrid)return;let targetY=nextGrid.getBoundingClientRect().top+minute*newScale;window.scrollBy({top:targetY-event.clientY,behavior:'instant'})})},{passive:false});
 document.querySelectorAll('[data-daily-tab]').forEach(button=>button.addEventListener('click',()=>{let active=button.dataset.dailyTab;document.querySelectorAll('[data-daily-panel]').forEach(panel=>panel.classList.toggle('hidden',panel.dataset.dailyPanel!==active));document.querySelectorAll('[data-daily-tab]').forEach(tab=>{let selected=tab.dataset.dailyTab===active;tab.classList.toggle('bg-zinc-950',selected);tab.classList.toggle('text-white',selected);tab.classList.toggle('text-zinc-500',!selected)})}));
 byId('form-start-time').addEventListener('input',updateEndPreview);byId('form-minutes').addEventListener('input',updateEndPreview);byId('form-division').addEventListener('change',()=>{refreshProjectOptions();updateEndPreview()});byId('form-project').addEventListener('change',()=>refreshKpiOptions());byId('proof-file').addEventListener('change',e=>{let file=e.target.files[0],label=byId('proof-file-name');label.textContent=file?`${file.name} · ${(file.size/1024/1024).toFixed(2)} MB`:'';label.classList.toggle('hidden',!file)});byId('proof-form').addEventListener('submit',submitProof);byId('reset-zoom').addEventListener('click',()=>{state.timelineScale=2;render()});byId('add-task').addEventListener('click',()=>openForm());byId('task-form').addEventListener('submit',saveForm);byId('user-filter').addEventListener('change',e=>{state.user=e.target.value;load(true)});byId('status-filter').addEventListener('change',render);byId('search-filter').addEventListener('input',render);byId('refresh').addEventListener('click',()=>load(true));load();
});
</script>
